import sys

def min_ones_after_transformations(n, m, grid):
    # Initialize variables to track the minimum number of 1s and the maximum number of 0s inverted
    min_ones, max_zeros_inverted = [float('inf')] * m, [0] * m

    # Process each row
    for i, row in enumerate(grid):
        zeros_inverted = 0
        for j, bit in enumerate(row):
            if bit == '0':
                zeros_inverted += 1
            else:
                min_ones = min(1 + min_ones[j], min_ones[j] + 1)
                max_zeros_inverted[j] = max(max_zeros_inverted[j], zeros_inverted)
        min_ones[i] = min_ones[i] + zeros_inverted

    # If min_ones is already set, then every cell is inverted
    if min_ones[0] != float('inf'):
        return 0

    # Iterate over columns and adjust the extreme values for total ones
    for k in range(1, m):
        if max_zeros_inverted[k - 1] < m / 2:
            min_ones[k] -= (max_zeros_inverted[k - 1] + 1) * (m - 1 - max_zeros_inverted[k])

    # The answer (atleast maximum possible number of ones times 2)
    if min_ones[0] != float('inf'):
        return min_ones[0] * 2

    return m * (n - min_ones)

