def shortest_path(n, m, t, edges, letters):
    graph = [[] for _ in range(n + 1)]
    letters_map = {i: [] for i in range(m + 1)}

    for i in t:
        v, u, c = i[0], i[1], ord(c) - ord('a')
        graph[v].append((u, c))
        graph[u].append((v, c))
        letters_map[v].append(letter(c))
        letters_map[u].append(letter(c))

    def letter(c):
        return chr(ord('a') + c)

    def bfs(start, graph):
        distances = [float('inf')] * (n + 1)
        dist_queue = [(0, start)]
        distances[start] = 0

        while dist_queue:
            dist, current = heappop(dist_queue)
            if dist > n:
                break
            if distances[current] < dist:
                continue
            for next_node, d in graph[current]:
                alt = diff(distances[current], d)
                if not alt:
                    dist_queue.append((dist + 1, next_node))
                elif alt < distances[next_node] + d:
                    heappush(dist_queue, (distances[next_node] + d, next_node))
                    distances[next_node] = alt

        return distances

    def diff(a, b):
        return abs(ord(a) - ord(b))

    for v, c in letters.values():
        bfs_shortest_path = bfs(v, graph)
        letters[v] = set([bfs_shortest_path(curr) for curr in graph[v]])

    power = [0] * (n + 1)
    for i, j in t:
        v, dist = bfs_shortest_path[i], bfs_shortest_path[j]
        seen = set()
        monster_power = 0
        for n in range(len(dist)):
            if dist[n] == i:
                n = len(dist) - 1
            else:
                if graph[i][n][1] == c:
                    if n == len(dist) - 1:
                        n = 0
                    else:
                        n += 1
                    if letters[dist[n]][v]:
                        break
                    d = diff(v, letters[dist[n]][v])
                    seen.add(d)
                while n < len(dist) - 1:
                    nxt = bfs_shortest_path[dist[n + 1]]
                    for s in seen:
                        if nxt[s]:
                            break
                        d = diff(v, nxt[s])
                        if not seen:
                            monster_power += s
                        curr_sp = bfs_shortest_path[v]
                        if curr_sp:
