import sys

class GroupMatcher:
    def __init__(self, teachers, students):
        # Build a graph where teachers are nodes and edges exist if they conflict with each other
        self.graph = defaultdict(set)
        for i in range(1, len(teachers)):
            if teachers[i] in teachers[i-1]:
                self.graph[i].add(i-1)

        # Sort students so we can rewire the edges that have changed
        self.students = list(students)
        self.students.sort()

    def can_assign(self, student, group):
        for prev_student, next_student in self.graph[group]:
            if self.students[student] == (self.students[prev_student], self.students[next_student]):
                return False

        return True

    def assign(self, student, group):
        self.students[student] = (self.students[group], self.students[student])
        return True

    def is_first_set(self, group):
        return self.students[group][1] > self.students[group][0]

class Solution:
