def bfs(graph, from_node, to_node, parent):
    if from_node == to_node:
        return True

    queue = deque([(graph[from_node], from_node)])
    while queue:
        ci, node = queue.popleft()
        for nei in graph[node]:
            if not nei in parent:
                queue.append((ci+1, nei))
                parent[nei] = node

    return False

def flow(graph_in, from_node, to_node, parent, head):
    if head == from_node == to_node:
        return graph_in[head]

