from collections import defaultdict

class FlowNetwork:
    def __init__(self, n, m, q):
        self.n = n
        self.m = m
        self.q = q
        self.nodes = defaultdict(list)
        self.capacities = [float('inf')] * q
        self.flow = [0] * (n + 1)
        self.prev = [-1] * (n + 1)

    def add_edge(self, x, y, c):
        if x != y:
            self.nodes[x].append((y, c))
            self.nodes[y].append((x, 0))

    def add_flow_change(self, i, delta):
        self.capacities[i] += delta
        self._update_flow(i)

    def add_edge_a_to_b(self, u, v, c):
        self.add_edge(u, v, c)
        self.add_edge(v, self.previous_edge_index(u), 0)
        for i in range(u, min(v, self.n)):
            self.add_edge(self.previous_edge_index(i), i + 1, self.capacities[self.previous_edge_index(i)])

    def add_flow(self, source, sink):
        edges = [(0, source)]  # The first edge from source
        self.flow[source] = 0  # The flow of source is 0
        self.prev[source] = -2
        prev = source
        while edges:
            u = edges.pop()
            prev = min(filter(lambda x: self.flow[x] + u.flow[x] < self.flow[x - 1] + u.flow[x - 1], u))
            for v, c in self.nodes[prev]:
                if c > 0 and self.flow[v] + prev.flow[v] < self.flow[v]:
                    edges.append((v, c - (self.flow[v] + prev.flow[v])))  
        return self.flow[-1] + self.flow[source]

    def _update_flow(self, u):
        self.flow[0] = min(self.flow[1], self.flow[u])
        for v in self.nodes[u]:
            self.prev[v[0]] = max(self.prev[u], max(self.prev[v[0]]))
            if self.flow[v[0]] + self.prev[u].flow[u] < self.flow[v[0]]:
                self.flow[v[0]] = min(self.flow[v[0]], self.flow[u] - self.flow[v[0]])

    def _previous_edge_index(self, u):
        prev = self.prev[u]
        if prev >= 0:
            return prev
        i = len(self.nodes[u]) - 1
        return i + 1

    def get_flow_network(self):
        return self.add_flow(1, self.n + 1)

def process_flow(t, total_flow, changes):
    while len(changes) >= t:
        change, capacity = changes.pop()
        if change == 1:
            total_flow += capacity * t
            for i in range(t):
                changes.append((-1, capacity))
        else:
            total_flow -= capacity * t
            for i in range(t):
                changes.append((change, -capacity))
    return total_flow
