from collections import defaultdict

def dfs_preorder(nodes, root):
    preorder = []
    def dfs(node, **data):
        preorder.append(node)
        for child in nodes[node]:
            if child != data.get('parent', root):
                dfs(child, parent=node)
    dfs(root)
    return preorder

def solve(n, k, balls, connections):
    nodes = defaultdict(list)
    for u, v in connections:
        nodes[u].append(v)
        nodes[v].append(u)

    max_grade = (1000000 + 5) // k
    heaps = [(ball, i) for i, ball in enumerate(balls)]
    heapify(heaps)

    for _ in range(k):
        current_grade = heappop(heaps)
        if sorted(nodes[current_grade[1]][-1:]):
            min_grade = min(max_grade, nodes[current_grade[1]][-1][1])
        elif sorted(nodes[current_grade[1]][-2:]):
            min_grade = min(max_grade - 1, nodes[current_grade[1]][-2][1])
        elif sorted(nodes[current_grade[1]][0:2]):
            min_grade = min(max_grade - 2, nodes[current_grade[1]][0][1])
        else:
            min_grade = min(max_grade - 2, nodes[current_grade[1]][1][1])
        max_grade = min_grade
        for ball, index in heaps:
            if sorted(nodes[ball][index:], reverse=True):
                min_grade = min(max_grade, nodes[ball][index][1])
            elif sorted(nodes[ball][index+1:], reverse=True):
                min_grade = min(max_grade - 1, nodes[ball][index+1][1])
            elif sorted(nodes[ball][:index+1], reverse=True):
                min_grade = min(max_grade - 2, nodes[ball][:index][1])
            else:
                min_grade = min(max_grade - 2, nodes[ball][:index+2][1])
        heappush(heaps, (max_grade, current_grade[1]))

    return max_grade

