    for i in range(len(rows)):
        for j in range(len(cols)):
            if adj_matrix[i][j] == '1':
                valid_destinations[i].append(abs(j - valid_destinations[i].index(max(valid_destinations[i]))))
            if adj_matrix[j][i] == '1':
                valid_destinations[j].append(abs(i - valid_destinations[j].index(max(valid_destinations[j]))))

    minimum_ones = float('inf')
