from math import gcd
from functools import reduce

def lcm(x, y):
    return x * y // gcd(x, y)

def dynamic_programming(n, graph, costs):
    dp = [0] * (1 << n)
    memo = {}

    def dp_helper(k, parent):
        if k in memo:
            return memo[k]
        if k == 0:
            return 0
        min_cost = float('inf')
        for child, cost in enumerate(graph[k]):
            if parent != child:
                new_cost = costs[child] + dp_helper(k ^ 1 << child, child)
                min_cost = min(min_cost, new_cost)
        memo[k] = min_cost
        return min_cost

    def calculate_expected_cost(node):
        if dp[(1 << n) - 1] == 0:
            dp[(1 << n) - 1] = dp_helper(1 << node, node)
        return dp[(1 << n) - 1]

    memo.clear()
    n_power = 2 ** n
    final_cost = 0
    for i in range(n):
        final_cost += calculate_expected_cost(i) * costs[i]
    return final_cost / n_power

