def min_targeted_cities(targeted_seq: str, direct_roads: List[List[int]]) -> int:
    N, M = len(targeted_seq), len(direct_roads)
    graph = [[] for _ in range(N + 1)]

    visited = [False] * (N + 1)

    for u, v, w in direct_roads:
        graph[u].append([v, w])
        graph[v].append([u, w])

    def is_subsequence(dest_city: int) -> bool:
        stack = [dest_city]
        visited[dest_city] = True

        while stack:
            current_city = stack.pop()
            for neighbor, weight in graph[current_city]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append(neighbor)

        return visited == [True] * (N + 1)

    for city in range(1, N + 1):
        if is_subsequence(city):
            return len(targeted_seq)

    return -1

