import heapq

def find_largest_enjoyment_and_payment(roads, toll_treaps, tours):
    enjoyment_maxes = [float('-inf')] * len(roads)
    max_heap = [(toll_treaps[i], i) for i in range(len(roads))]

    for tour_size, start_city in tours:
        smallest_toll = float('inf')
        largest_enjoyment = float('-inf')
        dists_from_starting_city = {}
        for end_city in range(len(roads)):
            if end_city == start_city:
                continue
            dists_from_starting_city[end_city] = (end_city, 0)
        heapq.heapify(dists_from_starting_city)

        traveled_tolls = set()
        while len(traveled_tolls) < tour_size:
            _, cost_tuple = heapq.heappop(dists_from_starting_city)
            cost = cost_tuple[1]
            start = cost_tuple[0]
            end = get_adj_cit(start, roads)
            if len(get_adj_cit(end, roads)) == 0:
                travel_dist = 0
            else:
                travel_dist = 1
            if (end, travel_dist) in traveled_tolls:
                continue
            traveled_tolls.add((end, travel_dist))
            cost_tuple = max(cost_tuple[0], toll_treaps[end] + cost)
            if (cost_tuple[0], end) in dists_from_starting_city:
                continue
            heapq.heappush(dists_from_starting_city, (cost_tuple, end))
            largest_enjoyment = max(largest_enjoyment, cost_tuple[1])
            enjoyment_maxes[end] = max(largest_enjoyment, enjoyment_maxes[end])
        enjoyment_maxes[start_city] = max(largest_enjoyment, enjoyment_maxes[start_city])
    return enjoyment_maxes

