class BinaryIndexedTree:
    def __init__(self, numElements):
        self.trees = [0] * (numElements + 1)
        self.numElements = numElements

    def update(self, idx, value):
        while idx < self.numElements:
            self.trees[idx] += value
            idx += idx & -idx

    def query(self, idx):
        ret = 0
        while idx > 0:
            ret += self.trees[idx]
            idx -= idx & -idx
        return ret

