import heapq
import sys

class NetworkFlow:
    def __init__(self, n, m, q, capacities):
        self.n = n
        self.m = m
        self.q = q
        self.capacities = capacities
        self.graph = [[] for _ in range(n + 1)]
        self.flow = [0] * n

    def add_edge(self, u, v, capacity):
        self.graph[u].append((v, capacity))
        self.graph[v].append((u, 0))

    def add_multiple_edges(self, u, v, edges):
        for w, capacity in edges:
            self.add_edge(u, v, capacity)

    def max_flow_from_to(self, src, sink):
        max_flow = 0
        while True:
            dist = [sys.maxsize] * self.n
            dist[src] = 0
            minq = []
            for i in range(1, self.n):
                if dist[i] >= dist[i + 1]:
                    heapq.heappush(minq, (dist[i], i))
            while minq:
                d, u = heapq.heappop(minq)
                for v, capacity in self.graph[u]:
                    if self.capacities[u][v] > 0 and 1 + dist[u] < dist[v]:
                        dist[v] = 1 + dist[u]
                        heapq.heappush(minq, (dist[v], v))
                self.capacities[u][v] -= 1
                self.capacities[v][u] += 1
                if dist[sink] == sys.maxsize:
                    break
            if dist[sink] == sys.maxsize:
                break
            self.flow[sink] += dist[sink]
            max_flow += 1
            for u in range(1, self.n):
                for v in range(u + 1, self.n):
                    self.capacities[u][v] += 1
        return max_flow

    def print_flow(self):
        return self.flow

    def update_capacity(self, u, new_capacity):
        capacity_i = new_capacity - self.capacities[u][u + 1]
        self.capacities[u][u + 1] = new_capacity
        if u < self.n - 1:
            self.capacities[u + 1][u] = capacity_i

    def maintain_flow_after_change(self, change):
        for u in range(self.n - 1):
            self.flow[u] = self.flow[u + 1]
        self.flow[self.n - 1] = self.flow[n]
        tmp_flows = [-1 * x for x in self.flow]
        self.add_edges(change)
        self.flow = [tmp_flows[i] for i in range(len(tmp_flows))]

    def add_edges(self, change):
        old_src_i, old_src_j = change
        self.add_edge(old_src_i, old_src_j, self.flow[old_src_i + 1] - self.flow[old_src_j - 1])
        self.add_edge(old_src_j, old_src_i, 0)
        self.flow[old_src_j - 1] = 0
        for u, v, next_capacity in self.edges_from(old_src_j):
            if u == old_src_i + 1:
                self.flow[next_capacity - 1] = next_capacity
                continue
            if self.flow[next_capacity - 1] != next_capacity:
                self.flow[next_capacity - 1] += self.flow[u - 1] - self.flow[v - 1]
                self.flow[u - 1] = self.flow[v - 1]

