def max_grade_with_root(root, grades, neighbors, time_limit, sorted_neighbors):
    dp = [0] * 27  # dp[root][i] represents the maximum grade that can be achieved with root at node i

    def dfs(node, parent):
        dp[node] = max(dp[node], grades[node])
        leader = -1
        for neighbor in sorted_neighbors[node]:
            if neighbor != parent:
                if dp[leader] + time_limit < dp[node]:
                    leader = neighbor
                dp[node] = max(dp[node], dfs(leader, node) + grades[node])
        return dp[node]

    return max(dfs(sorted_neighbors[root][0], -1) + grades[root], max(dp[root]) + time_limit)

