def calculate_possible_distribution(t, total_students, n, conflicting_pairs, students):
    conflicts = {}
    for i in range(n):
        for j in range(i, n):
            if i != j:
                conflicts[i, j] = set()
                for cpi, (lb, ub) in enumerate(student_student_pairs[i]):
                    if lb <= students[j][1] <= ub:
                        conflicts[i, j].add((cpi + 1, students[j][0]))
                        conflicts[i, j].add((cpi + 1, students[j][1]))

    dp = [float('inf')] * (total_students + 1)
    dp[0] = 0
    prev_dp = float('inf')

    for i in range(1, total_students + 1):
        if dp[i - 1] == float('inf'):
            dp[i] = i
        else:
            best_balance = min(dp[dp[i] - i] + (i - dp[i]) for i in range(1, n + 1) if i - dp[i] % n >= i)
            dp[i] = min(dp[i - 1] + n // (i - (prev_dp - i) % n), best_balance)
        prev_dp = dp[i]
        if dp[i] > t + 1:
            return "IMPOSSIBLE"

    if dp[total_students] > t:
        return "IMPOSSIBLE"

    balance = dp[total_students] - t
    group1 = dp[total_students - balance] - (total_students - balance)
    group2 = total_students - dp[total_students - balance]
    return f"POSSIBLE {group1} {group2}"

