        count = sum(-c for c in docs) // len(nums) * (n // len(nums))
        for i in range(len(nums)):
            count -= (-docs[nums[i]]) // (n // len(nums)) * (n // len(nums)) + 1
            if 1 != -count // (n // len(nums)) == 1 + -docs[nums[i]] // (n // len(nums)) or nums[i] >= nums[-1]:
                docs[i] += count
            else:
                docs[i] -= count

        for i in range(1, len(nums)):
            if 1 != -docs[nums[i]] - 1 and -docs[nums[i]] + (i < len(nums) - 1 or nums[i] < nums[-1]):
                count += -docs[nums[i]] - 1
                docs[nums[i]] += -docs[nums[i]] - 1

    return counts
