from itertools import permutations

def is_antipalindromic(s):
    if len(s) % 2 != 0:
        return False
    mid = len(s) // 2
    return all(s[i] != s[mid - i + 1] for i in range(mid + 1))

def calculate_beauty(s, beauties):
    beauty = 0
    for i, char in enumerate(s):
        beauty += beauties[i] if s[i] == char else beauties[i] + 1
    return beauty

def find_max_beauty(n, s, beauties):
    max_beauty = 0
    for perm in permutations(s):
        if is_antipalindromic(perm):
            current_beauty = calculate_beauty(perm, beauties)
            if current_beauty > max_beauty:
                max_beauty = current_beauty
    return max_beauty

