    seen = set()
    results = []

    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                for l in range(k+1, n):
                    sum_xor = A[i] ^ A[j] ^ A[k] ^ A[l]
                    xor_count = popcount(sum_xor)
                    if xor_count == 3:
                        results.append((i, j, k, l))
                        break
            else:
                continue
            break
        else:
            continue
        break

    return [result for result in results if result not in seen]
    seen.add(result)

