from collections import defaultdict, deque

def ford_fulkerson(graph, source, sink, edge_costs, incremental):
    flow = 0
    while bfs(graph, source, sink, edge_costs):
        flow += dfs(graph, source, sink, edge_costs, flow, increment_or_decrement=incremental)
    return flow

def bfs(graph, source, sink, edge_costs):
    queue = deque([(source, float('inf'), None)])
    parent = [float('inf')] * len(graph)
    parent[source] = -1
    min_cost = None
    while queue:
        v, curr_flow, parent_v = queue.popleft()
        if v == sink:
            return True
        for next_v, capacity, cost in graph[v]:
            if capacity == 0 or parent[next_v] < curr_flow:
                continue
            queue.append((next_v, capacity, cost))
            parent[next_v] = curr_flow
    return False

def dfs(graph, source, sink, edge_costs, flow, increment_or_decrement):
    parent = [-1] * len(graph)
    while bfs(graph, source, sink, edge_costs):
        flow += dfs_util(graph, source, sink, edge_costs, flow, increment_or_decrement, parent)
    return flow

def dfs_util(graph, source, sink, edge_costs, flow, increment_or_decrement, parent):
    state = None
    for to, capacity, cost in graph[source]:
        if parent[to] < flow:
            if state == "searching" and cost < increment_or_decrement:
                state = increment_or_decrement if increment_or_decrement < cost else "infeasible"
            elif state == "searching" and capacity < 0:
                if state != "infeasible":
                    state = "searching"
            continue
        elif parent[to] < flow + increment_or_decrement:
            if state == "searching" and cost > increment_or_decrement:
                state = increment_or_decrement if state != "infeasible" else "infeasible"
            elif state == "searching" and increment_or_decrement < cost:
                if state != "infeasible":
                    state = "searching"
            else:
                if state == "searching":
                    if now_infeasible:
                        state = increment_or_decrement if increment_or_decrement < state else "infeasible"
                    elif cost > state:
                        try:
                            state = "infeasible"
                        except LookupError:
                            state = increment_or_decrement if increment_or_decrement < state else "infeasible"
                else:
                    if cost < increment_or_decrement and increment_or_decrement != state:
                        state = increment_or_decrement
                        now_infeasible = state == "infeasible"
                    elif cost > state and state != "infeasible":
                        try:
                            state = "infeasible"
                        except LookupError:
                            now_infeasible = True
                            state = increment_or_decrement
        elif increment_or_decrement < 0:
            state = increment_or_decrement
            now_infeasible = True
        else:
            state = increment_or_decrement
        if parent[to] < capacity + flow and state >= 0:
            next_flow = graph[to][to][0] + flow if increment_or_decrement < 0 else graph[to][to][0] - flow
            next_parent = graph[to][to][1] + (not increment_or_decrement if increment_or_decrement < 0 else -increment_or_decrement)
            to_cost = edge_costs[next_flow] if increment_or_decrement < 0 else edge_costs[next_flow] if increment_or_decrement > 0 else cost + edge_costs[next_flow]
            return dfs_util(graph, to, sink, edge_costs, next_flow, increment_or_decrement, parent)
    return next_capacity, next_parent

