from collections import deque

def min_cost_to_end_round(p, a, b, x, rounds, S):
    dp = [0] * (len(rounds) + 1)

    for i in range(len(rounds)):
        cost = 0
        cur = deque()

        if S and rounds[S][0] >= x and p[S] < p[i]:
            cur.append((p[S], dp[S]))

        for j in range(len(rounds[i])):
            next_cost, cum_cost = dp[rounds[i][j]], b[rounds[i][j]] + cost

            if S and S not in cur:
                if p[S] < p[i]:
                    cur.append((p[S], dp[S]))

            for k in range(len(rounds[i]) - 1, -1, -1):
                if S not in cur and cur and cur[0][0] >= p[j]:
                    break

                next_cost = min(next_cost, cum_cost + dp[rounds[i][k]])

            cost = next_cost

        dp[i + 1] = cost

    return dp[rounds[i]]

